CREATE OR REPLACE FUNCTION rakeezx.force_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.owner_id := auth.uid();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION rakeezx.guard_archived_section_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_section text; v_old_section text; v_status text;
begin
  if pg_catalog.current_setting('rakeezx.section_lifecycle_delete', true) = 'on' then return new; end if;
  v_section := rakeezx.section_for_operational_row(tg_table_name, to_jsonb(new));
  if tg_op = 'UPDATE' then v_old_section := rakeezx.section_for_operational_row(tg_table_name, to_jsonb(old)); end if;
  for v_section in select distinct candidate from unnest(array[v_section,v_old_section]) candidate where candidate is not null order by candidate loop
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(new.owner_id::text||':section-lifecycle:'||v_section,0));
    select status into v_status from rakeezx.sections where owner_id=new.owner_id and id=v_section and deleted_at is null;
    if v_status = 'archived' then
      raise exception using errcode='22023', message='Archived section is read-only';
    end if;
  end loop;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.guard_closed_term_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if old.status = 'closed' and pg_catalog.to_jsonb(new) is distinct from pg_catalog.to_jsonb(old) then
    raise exception using errcode = '22023', message = 'Closed term is immutable';
  end if;
  if old.status <> 'closed' and new.status = 'closed' and
     coalesce(pg_catalog.current_setting('rakeezx.closed_term_report_write',true),'') <> 'on' then
    raise exception using errcode = '22023', message = 'Term closure requires its report command';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION rakeezx.guard_live_student_parent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_student text; v_students text[] := '{}'; v_section text;
begin
  -- Match force_owner BEFORE taking a lock or checking parent identity. A
  -- caller-supplied owner must not select another account's safety boundary.
  if tg_op='INSERT' and auth.uid() is not null then new.owner_id:=auth.uid(); end if;
  -- Statement gate / RPC entry already holds the owner lock before row locks.
  if tg_table_name='students' and tg_op='UPDATE' then
    if old.deleted_at is not null and new.deleted_at is null then
      raise exception using errcode='23503',message='STUDENT_TOMBSTONED';
    end if;
    if old.deleted_at is null and new.deleted_at is not null and
      coalesce(current_setting('rakeezx.pristine_student_delete',true),'')<>'on' then
      raise exception using errcode='22023',message='USE_PRISTINE_STUDENT_COMMAND';
    end if;
  end if;
  if tg_table_name in ('enrollments','scores','attendance','logs','notes') then
    if new.deleted_at is not null then return new; end if;
    v_students := array[new.student_id];
  elsif tg_table_name='session_roster_snapshots' then
    -- Snapshot reads and immutable historical members are untouched.
    if tg_op<>'INSERT' or new.deleted_at is not null then return new; end if;
    select coalesce(array_agg(m->>'studentId'),'{}') into v_students
      from pg_catalog.jsonb_array_elements(new.members) m;
  end if;
  foreach v_student in array v_students loop
    if not exists(select 1 from rakeezx.students where owner_id=new.owner_id and id=v_student and deleted_at is null) then
      raise exception using errcode='23503',message='STUDENT_TOMBSTONED',detail='Active child evidence requires a live student';
    end if;
  end loop;
  if tg_table_name in ('logs','attendance') then
  if tg_op='INSERT' and new.deleted_at is null then
    select section_id into v_section from rakeezx.teachings where owner_id=new.owner_id and id=new.teaching_id;
    if exists(select 1 from rakeezx.enrollments where owner_id=new.owner_id and student_id=new.student_id
      and section_id=v_section and status<>'active' and end_date is not null and new.date>=end_date and deleted_at is null)
      and not exists(select 1 from rakeezx.enrollments where owner_id=new.owner_id and student_id=new.student_id
        and section_id=v_section and status='active' and deleted_at is null) then
      raise exception using errcode='23503',message='ENROLLMENT_ENDED';
    end if;
  end if;
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.guard_safe_session_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_blocker text;
begin
  if old.deleted_at is not null or new.deleted_at is null then return new; end if;
  -- Validated class lifecycle and V2 restore already enforce their own complete
  -- transaction contract and use this established transaction-local bypass.
  if pg_catalog.current_setting('rakeezx.section_lifecycle_delete',true)='on' then return new; end if;
  v_blocker := rakeezx.session_delete_blocker(old.owner_id,old.id);
  if v_blocker is not null then
    raise exception using errcode='23514',message='Session contains retained historical evidence',detail=v_blocker;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION rakeezx.guard_subitem_definition_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if pg_catalog.current_setting('rakeezx.score_domain_write',true) is distinct from 'on' then
    if tg_table_name='items' then
      if new.score_mode='subitems' or (tg_op='UPDATE' and old.score_mode='subitems') then
        raise exception using errcode='42501',message='Subitem configuration requires atomic score domain command';
      end if;
    else
      raise exception using errcode='42501',message='Subitem mutation requires atomic score domain command';
    end if;
  end if;
  if tg_table_name='score_subitems' and tg_op='UPDATE' and
      new.created_at is distinct from old.created_at then
    raise exception using errcode='42501',message='Subitem creation history is immutable';
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.n58_guard_calendar_contract()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_row jsonb; v_old jsonb; v_year rakeezx.years%rowtype;
  v_calendar rakeezx.calendars%rowtype; v_term rakeezx.terms%rowtype;
  v_year_id text; v_context jsonb; v_fresh_restore boolean;
begin
  if tg_op='INSERT' and auth.uid() is not null then new.owner_id:=auth.uid(); end if;
  v_row:=case when tg_op='DELETE' then pg_catalog.to_jsonb(old) else pg_catalog.to_jsonb(new) end;
  if tg_op='UPDATE' then
    v_old:=pg_catalog.to_jsonb(old);
    if (new.owner_id,new.id) is distinct from (old.owner_id,old.id) then
      raise exception using errcode='22023',message='N58_IMMUTABLE_RECORD_IDENTITY'; end if;
    -- Preserve the existing tombstone trigger's silent, immutable update result.
    if old.deleted_at is not null then return null; end if;
  end if;

  case tg_table_name
    when 'years' then v_year_id:=v_row->>'id';
    when 'terms','calendars','sections' then v_year_id:=v_row->>'year_id';
    when 'calendar_days' then
      select * into v_calendar from rakeezx.calendars where owner_id=(v_row->>'owner_id')::uuid
        and id=v_row->>'calendar_id';
      v_year_id:=v_calendar.year_id;
    when 'teachings' then
      select * into v_term from rakeezx.terms where owner_id=(v_row->>'owner_id')::uuid and id=v_row->>'term_id';
      v_year_id:=v_term.year_id;
    when 'sessions' then
      select t.* into v_term from rakeezx.terms t join rakeezx.teachings x
        on x.owner_id=t.owner_id and x.term_id=t.id
        where x.owner_id=(v_row->>'owner_id')::uuid and x.id=v_row->>'teaching_id';
      v_year_id:=v_term.year_id;
  end case;
  select * into v_year from rakeezx.years where owner_id=(v_row->>'owner_id')::uuid and id=v_year_id;
  v_fresh_restore:=rakeezx.n58_restore_creating_year((v_row->>'owner_id')::uuid,v_year_id);

  if tg_table_name='years' then
    if tg_op='DELETE' then
      if old.calendar_preset_id is not null then
        raise exception using errcode='22023',message='N58_SELECTED_YEAR_RETIREMENT_BLOCKED'; end if;
    else
      if new.calendar_preset_id is not null and not rakeezx.n58_valid_preset(new.calendar_preset_id,new.hijri_start,new.hijri_end) then
        raise exception using errcode='22023',message='N58_UNSUPPORTED_YEAR_PRESET'; end if;
      if tg_op='UPDATE' and old.calendar_preset_id is not null and
        (new.calendar_preset_id is null or new.deleted_at is not null or
          (new.hijri_start,new.hijri_end) is distinct from (old.hijri_start,old.hijri_end)) then
        raise exception using errcode='22023',message='N58_SELECTED_YEAR_IDENTITY_BLOCKED'; end if;
      if new.calendar_preset_id is not null and new.deleted_at is not null then
        raise exception using errcode='22023',message='N58_SELECTED_YEAR_RETIREMENT_BLOCKED'; end if;
      if new.calendar_preset_id is not null and not v_fresh_restore and
        (select count(*) from rakeezx.terms t where t.owner_id=new.owner_id and t.year_id=new.id
          and t."index" in (1,2) and t.deleted_at is null)<>2 then
        raise exception using errcode='22023',message='N58_EXISTING_TERMS_REQUIRED'; end if;
      if tg_op='UPDATE' and exists(select 1 from rakeezx.calendars c where c.owner_id=new.owner_id
        and c.year_id=new.id and c.preset_id is not null and
        not rakeezx.n58_valid_preset(c.preset_id,new.hijri_start,new.hijri_end)) then
        raise exception using errcode='22023',message='N58_SCOPED_YEAR_IDENTITY_BLOCKED'; end if;
    end if;
  elsif tg_table_name='calendars' then
    if tg_op='UPDATE' and (new.year_id,new.source,new.preset_id) is distinct from (old.year_id,old.source,old.preset_id) then
      raise exception using errcode='22023',message='N58_IMMUTABLE_CALENDAR_SCOPE'; end if;
    if tg_op='DELETE' then
      if old.preset_id is not null or v_year.calendar_preset_id is not null then
        raise exception using errcode='22023',message='N58_CALENDAR_HARD_DELETE_BLOCKED'; end if;
    else
      if new.preset_id is not null and (new.source<>'custom' or v_year.deleted_at is not null or
        not rakeezx.n58_valid_preset(new.preset_id,v_year.hijri_start,v_year.hijri_end)) then
        raise exception using errcode='22023',message='N58_INVALID_CUSTOM_SCOPE'; end if;
      if not v_fresh_restore then
        perform rakeezx.n58_validate_overrides(new.owner_id,new.year_id,new.preset_id,new.term_date_overrides);
      end if;
      if v_year.calendar_preset_id is not null and new.preset_id is null and not v_fresh_restore and
        (tg_op='INSERT' or (v_row-array['updated_at','client_updated_at','device_id','revision','field_revisions']) is distinct from
          (v_old-array['updated_at','client_updated_at','device_id','revision','field_revisions'])) then
        raise exception using errcode='22023',message='N58_LEGACY_CALENDAR_WRITE_BLOCKED'; end if;
    end if;
  elsif tg_table_name='calendar_days' then
    if tg_op='UPDATE' and (new.calendar_id,new.date) is distinct from (old.calendar_id,old.date) then
      raise exception using errcode='22023',message='N58_IMMUTABLE_DAY_IDENTITY'; end if;
    if v_year.calendar_preset_id is not null and not v_fresh_restore then
      if tg_op='DELETE' or v_calendar.preset_id is null or v_calendar.deleted_at is not null then
        if tg_op='UPDATE' and v_row-array['updated_at','client_updated_at','device_id','revision','field_revisions'] =
          v_old-array['updated_at','client_updated_at','device_id','revision','field_revisions'] then return new; end if;
        raise exception using errcode='22023',message='N58_UNSCOPED_DAY_WRITE_BLOCKED'; end if;
    end if;
  elsif tg_table_name='terms' then
    if tg_op='UPDATE' and (new.year_id,new."index") is distinct from (old.year_id,old."index") then
      raise exception using errcode='22023',message='N58_IMMUTABLE_TERM_IDENTITY'; end if;
    if v_year.calendar_preset_id is not null then
      if not v_fresh_restore and (tg_op='DELETE' or (tg_op='UPDATE' and new.deleted_at is not null)) then
        raise exception using errcode='22023',message='N58_TERM_RETIREMENT_BLOCKED'; end if;
      if not v_fresh_restore and ((tg_op='INSERT' and (new.start_date is not null or new.end_date is not null or new.calendar_id is not null)) or
        (tg_op='UPDATE' and (new.start_date,new.end_date,new.calendar_id) is distinct from (old.start_date,old.end_date,old.calendar_id))) then
        raise exception using errcode='22023',message='N58_USE_SCOPED_TERM_OVERRIDES'; end if;
    end if;
    -- An override cannot be orphaned even in a prepared, not-yet-selected scope.
    if tg_op='DELETE' or (tg_op='UPDATE' and new.deleted_at is not null) then
      if exists(select 1 from rakeezx.calendars c where c.owner_id=(v_row->>'owner_id')::uuid
        and c.year_id=v_year_id and c.deleted_at is null and c.term_date_overrides ? (v_row->>'id')) then
        raise exception using errcode='22023',message='N58_OVERRIDE_TERM_RETIREMENT_BLOCKED'; end if;
    end if;
  elsif tg_table_name in ('teachings','sections') then
    if tg_op='UPDATE' and (v_year.calendar_preset_id is not null or
      (tg_table_name='sections' and exists(select 1 from rakeezx.years y where y.owner_id=new.owner_id
        and y.id=v_old->>'year_id' and y.calendar_preset_id is not null)) or
      (tg_table_name='teachings' and exists(select 1 from rakeezx.terms t join rakeezx.years y
        on y.owner_id=t.owner_id and y.id=t.year_id where t.owner_id=new.owner_id
        and t.id=v_old->>'term_id' and y.calendar_preset_id is not null))) and ((tg_table_name='teachings' and
      (v_row->>'section_id',v_row->>'subject_id',v_row->>'term_id') is distinct from
      (v_old->>'section_id',v_old->>'subject_id',v_old->>'term_id')) or
      (tg_table_name='sections' and v_row->>'year_id' is distinct from v_old->>'year_id')) then
      -- Retain the stable parent identity used by recorded contexts/history.
      raise exception using errcode='22023',message='N58_IMMUTABLE_TEACHING_PARENT'; end if;
    if tg_table_name='teachings' and v_year.calendar_preset_id is not null and tg_op<>'DELETE' and
      not exists(select 1 from rakeezx.sections s where s.owner_id=(v_row->>'owner_id')::uuid and s.id=v_row->>'section_id' and s.year_id=v_year_id) then
      raise exception using errcode='22023',message='N58_TEACHING_YEAR_MISMATCH'; end if;
  elsif tg_table_name='sessions' and tg_op<>'DELETE' then
    if tg_op='UPDATE' then
      if new.calendar_context is distinct from old.calendar_context then
        raise exception using errcode='22023',message='N58_IMMUTABLE_SESSION_CONTEXT'; end if;
      if (old.calendar_context is not null or v_year.calendar_preset_id is not null or
        exists(select 1 from rakeezx.teachings x join rakeezx.terms t on t.owner_id=x.owner_id and t.id=x.term_id
          join rakeezx.years y on y.owner_id=t.owner_id and y.id=t.year_id
          where x.owner_id=old.owner_id and x.id=old.teaching_id and y.calendar_preset_id is not null)) and
        (new.teaching_id,new.date,new.period) is distinct from (old.teaching_id,old.date,old.period) then
        raise exception using errcode='22023',message='N58_IMMUTABLE_SESSION_IDENTITY'; end if;
    else
      v_context:=new.calendar_context;
      if v_context is null and v_year.calendar_preset_id is not null and not v_fresh_restore then
        raise exception using errcode='22023',message='N58_SESSION_CONTEXT_REQUIRED'; end if;
      if v_context is not null then
        if pg_catalog.jsonb_typeof(v_context)<>'object' or pg_catalog.octet_length(v_context::text)>2048 or
          not (v_context ?& array['yearId','termId','presetId','selectionRevision','kind','source']) or
          v_context-array['yearId','termId','presetId','selectionRevision','kind','source','label']<>'{}'::jsonb or
          pg_catalog.jsonb_typeof(v_context->'yearId')<>'string' or pg_catalog.jsonb_typeof(v_context->'termId')<>'string' or
          pg_catalog.jsonb_typeof(v_context->'presetId')<>'string' or pg_catalog.jsonb_typeof(v_context->'kind')<>'string' or
          pg_catalog.jsonb_typeof(v_context->'source')<>'string' or
          (v_context ? 'label' and (pg_catalog.jsonb_typeof(v_context->'label')<>'string' or pg_catalog.length(v_context->>'label')>500)) or
          pg_catalog.jsonb_typeof(v_context->'selectionRevision')<>'number' or
          (v_context->>'selectionRevision') !~ '^[1-9][0-9]{0,17}$' or
          v_context->>'yearId' is distinct from v_year_id or v_context->>'termId' is distinct from v_term.id or
          not rakeezx.n58_valid_preset(v_context->>'presetId',v_year.hijri_start,v_year.hijri_end) or
          v_context->>'kind' not in ('study','holiday','national','founding','exam','event','remote','suspension') or
          v_context->>'source' not in ('custom','official','default') or v_term.deleted_at is not null or v_year.deleted_at is not null or
          not exists(select 1 from rakeezx.teachings x where x.owner_id=new.owner_id and x.id=new.teaching_id and x.deleted_at is null) then
          raise exception using errcode='22023',message='N58_INVALID_SESSION_CONTEXT'; end if;
        if not v_fresh_restore and (v_year.calendar_preset_id is null or
          v_context->>'presetId' is distinct from v_year.calendar_preset_id or
          (v_context->>'selectionRevision')::bigint is distinct from (v_year.field_revisions->>'calendar_selection')::bigint) then
          raise exception using errcode='40001',message='N58_STALE_CALENDAR_SELECTION'; end if;
      end if;
    end if;
  end if;
  if tg_op='DELETE' then return old; else return new; end if;
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.n58_revalidate_effective_scope_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid; v_year text; v_stage record;
begin
  if tg_table_name='n58_restore_transactions' then
    -- The existing finalizer removes this marker only after all staged rows exist.
    for v_stage in select distinct o->>'recordId' year_id
      from rakeezx.sync_restore_stages s
      cross join lateral pg_catalog.jsonb_array_elements(s.operations) o
      where s.owner_id=old.owner_id and s.restore_id=old.restore_id
        and o->>'entity'='years' and o->>'operation'='create' loop
      perform rakeezx.n58_validate_effective_year(old.owner_id,v_stage.year_id);
    end loop;
    return old;
  end if;
  if tg_table_name='years' then
    v_owner:=new.owner_id; v_year:=new.id;
  elsif tg_op='DELETE' then
    v_owner:=old.owner_id; v_year:=old.year_id;
  else
    v_owner:=new.owner_id; v_year:=new.year_id;
  end if;
  if not rakeezx.n58_restore_creating_year(v_owner,v_year) then
    perform rakeezx.n58_validate_effective_year(v_owner,v_year);
  end if;
  if tg_op='DELETE' then return old; else return new; end if;
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.n71_guard_portable_parent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_teaching text; v_assignment rakeezx.assignments%rowtype;
begin
  if tg_op='INSERT' then new.owner_id:=auth.uid(); end if;
  if new.deleted_at is not null then return new; end if;
  if tg_table_name='submissions' then
    select * into v_assignment from rakeezx.assignments where owner_id=new.owner_id and id=new.assignment_id and deleted_at is null;
    if not found or not exists(select 1 from rakeezx.students where owner_id=new.owner_id and id=new.student_id and deleted_at is null) then
      raise exception using errcode='23503',message='N71 portable parent is unavailable'; end if;
    if new.score>v_assignment.max then raise exception using errcode='22023',message='N71 submission score exceeds maximum'; end if;
    v_teaching:=v_assignment.teaching_id;
  else
    v_teaching:=new.teaching_id;
    if exists(select 1 from rakeezx.submissions where owner_id=new.owner_id
      and assignment_id=new.id and deleted_at is null and score>new.max) then
      raise exception using errcode='22023',message='N71 assignment maximum would invalidate a submission'; end if;
    if new.lesson_id is not null and not exists(select 1 from rakeezx.lessons l join rakeezx.units u
      on u.owner_id=l.owner_id and u.id=l.unit_id join rakeezx.teachings t
      on t.owner_id=u.owner_id and t.subject_id=u.subject_id
      where l.owner_id=new.owner_id and l.id=new.lesson_id and t.id=v_teaching
        and l.deleted_at is null and u.deleted_at is null) then
      raise exception using errcode='23503',message='N71 lesson scope is unavailable'; end if;
    if new.item_id is not null and not exists(select 1 from rakeezx.items
      where owner_id=new.owner_id and id=new.item_id and teaching_id=v_teaching and deleted_at is null) then
      raise exception using errcode='23503',message='N71 item scope is unavailable'; end if;
  end if;
  if not exists(select 1 from rakeezx.teachings t join rakeezx.sections s
    on s.owner_id=t.owner_id and s.id=t.section_id join rakeezx.terms tm
    on tm.owner_id=t.owner_id and tm.id=t.term_id join rakeezx.years y
    on y.owner_id=tm.owner_id and y.id=tm.year_id
    where t.owner_id=new.owner_id and t.id=v_teaching and t.deleted_at is null
      and s.deleted_at is null and s.status='active' and tm.deleted_at is null
      and tm.status<>'closed' and y.deleted_at is null) then
    raise exception using errcode='23503',message='N71 teaching scope is unavailable or closed'; end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.n77_guard_live_parent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row jsonb := pg_catalog.to_jsonb(new);
  v_owner uuid := new.owner_id;
  v_section text := v_row->>'section_id';
  v_teaching text := v_row->>'teaching_id';
  v_item text := v_row->>'item_id';
  v_subitem text := v_row->>'subitem_id';
  v_session text := v_row->>'session_id';
  v_student text := v_row->>'student_id';
  v_parent rakeezx.sections%rowtype;
begin
  if v_row->>'deleted_at' is not null then return new; end if;
  if v_student is not null and not exists (
    select 1 from rakeezx.students where owner_id=v_owner and id=v_student and deleted_at is null
  ) then raise exception using errcode='22023',message='N77 student is unavailable'; end if;
  if v_subitem is not null then
    select si.item_id into v_item from rakeezx.score_subitems si
      where si.owner_id=v_owner and si.id=v_subitem and si.deleted_at is null;
    if v_item is null then raise exception using errcode='22023',message='N77 subitem is unavailable'; end if;
  end if;
  if v_item is not null then
    select i.teaching_id into v_teaching from rakeezx.items i
      where i.owner_id=v_owner and i.id=v_item and i.deleted_at is null;
    if v_teaching is null then raise exception using errcode='22023',message='N77 item is unavailable'; end if;
  end if;
  if v_session is not null then
    if v_teaching is null then
      select s.teaching_id into v_teaching from rakeezx.sessions s
        where s.owner_id=v_owner and s.id=v_session and s.deleted_at is null;
      if v_teaching is null then raise exception using errcode='22023',message='N77 session is unavailable'; end if;
    elsif not exists (select 1 from rakeezx.sessions s where s.owner_id=v_owner and s.id=v_session
      and s.teaching_id=v_teaching and s.deleted_at is null) then
      raise exception using errcode='22023',message='N77 session scope mismatch';
    end if;
  end if;
  if v_teaching is not null then
    select t.section_id into v_section from rakeezx.teachings t
      where t.owner_id=v_owner and t.id=v_teaching and t.deleted_at is null;
    if v_section is null then raise exception using errcode='22023',message='N77 teaching is unavailable'; end if;
  end if;
  if v_section is not null then
    select * into v_parent from rakeezx.sections
      where owner_id=v_owner and id=v_section for share;
    if not found or v_parent.deleted_at is not null then
      raise exception using errcode='22023',message='N77 section is unavailable';
    end if;
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.record_owner_sync_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid; v_revision bigint;
begin
  if TG_OP='UPDATE' and NEW is not distinct from OLD then return NEW; end if;
  if TG_OP='DELETE' then v_owner:=OLD.owner_id; else v_owner:=NEW.owner_id; end if;
  if TG_OP='UPDATE' and NEW.owner_id is distinct from OLD.owner_id then
    raise exception 'Owner identity is immutable' using errcode='42501';
  end if;
  if auth.uid() is not null and auth.uid()<>v_owner then
    raise exception 'Owner mismatch' using errcode='42501';
  end if;
  -- Account deletion cascades must not recreate its marker.
  if not exists(select 1 from auth.users where id=v_owner) then
    if TG_OP='DELETE' then return OLD; else return NEW; end if;
  end if;
  insert into rakeezx.owner_sync_changes(owner_id,revision,updated_at)
    values(v_owner,1,clock_timestamp())
    on conflict(owner_id) do update set revision=owner_sync_changes.revision+1,
      updated_at=clock_timestamp() returning revision into v_revision;
  perform realtime.send(jsonb_build_object('revision',v_revision::text),
    'invalidate','rakeezx-owner:'||v_owner::text,true);
  if TG_OP='DELETE' then return OLD; else return NEW; end if;
end;
$function$

CREATE OR REPLACE FUNCTION rakeezx.sync_v2_stamp_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_field_map jsonb := rakeezx.sync_v2_field_map(tg_table_name);
  v_field text;
  v_group text;
  v_next_revision bigint;
  v_revisions jsonb;
  v_changed boolean := false;
begin
  if tg_op = 'INSERT' then
    new.revision := 1;
    new.field_revisions := rakeezx.sync_v2_initial_field_revisions(tg_table_name, 1);
    if new.deleted_at is not null then
      new.field_revisions := pg_catalog.jsonb_set(
        new.field_revisions, array['__deleted__'], '1'::jsonb, true
      );
    end if;
    return new;
  end if;

  -- A tombstone is immutable through every generic write path. Returning NULL
  -- skips the row update entirely, including metadata churn. A future restore
  -- requires a separate validated command rather than an UPDATE bypass.
  if old.deleted_at is not null then
    return null;
  end if;

  v_next_revision := old.revision + 1;
  v_revisions := coalesce(old.field_revisions, '{}'::jsonb);
  for v_field, v_group in
    select entry.key, entry.value #>> '{}'
    from pg_catalog.jsonb_each(v_field_map) as entry
  loop
    if (pg_catalog.to_jsonb(new) -> v_field) is distinct from (pg_catalog.to_jsonb(old) -> v_field) then
      v_changed := true;
      v_revisions := pg_catalog.jsonb_set(v_revisions, array[v_group], pg_catalog.to_jsonb(v_next_revision), true);
    end if;
  end loop;
  if new.deleted_at is distinct from old.deleted_at then
    v_changed := true;
    v_revisions := pg_catalog.jsonb_set(v_revisions, array['__deleted__'], pg_catalog.to_jsonb(v_next_revision), true);
  end if;

  -- The server revision describes domain mutations, not device/timestamp
  -- bookkeeping. Preserve the current revision for an identical/no-op patch.
  if not v_changed then
    new.revision := old.revision;
    new.field_revisions := old.field_revisions;
    return new;
  end if;

  new.revision := v_next_revision;
  new.field_revisions := v_revisions;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION rakeezx.touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at := pg_catalog.now();
  if new.owner_id is null then
    new.owner_id := auth.uid();
  end if;
  return new;
end;
$function$
